{
  "name": "Helicopter Inspector",
  "description": "A humorous and satirical 2D arcade-style game where you play as 'Minister Milon', flying a helicopter to catch students cheating in exams. Use your spotlight to find and catch cheaters, but be careful not to accuse the innocent! A fun parody about academic integrity."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useCallback } from 'react';
import MainMenu from './components/MainMenu';
import GameScreen from './components/GameScreen';
import GameOverScreen from './components/GameOverScreen';
import { GameState } from './types';
import { LEVELS } from './constants';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.MENU);
  const [level, setLevel] = useState(1);
  const [score, setScore] = useState(0);
  const [finalScore, setFinalScore] = useState(0);

  const handleStartGame = useCallback(() => {
    setLevel(1);
    setScore(0);
    setGameState(GameState.PLAYING);
  }, []);

  const handleLevelComplete = useCallback(() => {
    if (level < LEVELS.length) {
      setLevel(prevLevel => prevLevel + 1);
    } else {
      setFinalScore(score);
      setGameState(GameState.GAME_OVER);
    }
  }, [level, score]);

  const handleGameOver = useCallback((currentScore: number) => {
    setFinalScore(currentScore);
    setGameState(GameState.GAME_OVER);
  }, []);

  const renderScreen = () => {
    switch (gameState) {
      case GameState.MENU:
        return <MainMenu onStartGame={handleStartGame} />;
      case GameState.PLAYING:
        const currentLevel = LEVELS[level - 1];
        if (!currentLevel) {
            // Fallback if level data is missing
            return <GameOverScreen score={score} onPlayAgain={handleStartGame} message="Error: Level not found!" />;
        }
        return (
          <GameScreen
            levelConfig={currentLevel}
            onLevelComplete={handleLevelComplete}
            onGameOver={handleGameOver}
            score={score}
            setScore={setScore}
          />
        );
      case GameState.GAME_OVER:
        return <GameOverScreen score={finalScore} onPlayAgain={handleStartGame} />;
      default:
        return <MainMenu onStartGame={handleStartGame} />;
    }
  };

  return (
    <div className="flex items-center justify-center h-screen bg-blue-400 font-sans">
      {renderScreen()}
    </div>
  );
};

export default App;

export enum GameState {
  MENU,
  PLAYING,
  GAME_OVER,
}

export enum CheatType {
    NONE,
    PAPER,
    PHONE,
    WHISPER,
    DECOY,
}

export interface Student {
  id: number;
  x: number;
  y: number;
  cheatType: CheatType;
  isCheating: boolean;
  isCaught: boolean;
  isFalselyAccused: boolean;
  cheatTimer: number;
}

export interface Level {
  level: number;
  name: string;
  duration: number;
  studentSpawnRate: number; // in milliseconds
  cheatingChance: number; // 0 to 1
  maxStudents: number;
  hasDecoys: boolean;
  isNightMode: boolean;
}

import { Level } from './types';

export const GAME_WIDTH = 800;
export const GAME_HEIGHT = 600;
export const HELICOPTER_SPEED = 20;
export const SPOTLIGHT_RADIUS = 75;

export const LEVELS: Level[] = [
  {
    level: 1,
    name: "School Exams",
    duration: 60,
    studentSpawnRate: 3000,
    cheatingChance: 0.3,
    maxStudents: 5,
    hasDecoys: false,
    isNightMode: false,
  },
  {
    level: 2,
    name: "College Exams",
    duration: 50,
    studentSpawnRate: 2500,
    cheatingChance: 0.4,
    maxStudents: 7,
    hasDecoys: false,
    isNightMode: false,
  },
  {
    level: 3,
    name: "University Exams",
    duration: 45,
    studentSpawnRate: 2000,
    cheatingChance: 0.5,
    maxStudents: 8,
    hasDecoys: true,
    isNightMode: false,
  },
  {
    level: 4,
    name: "Bonus: Night Exam",
    duration: 60,
    studentSpawnRate: 2200,
    cheatingChance: 0.6,
    maxStudents: 6,
    hasDecoys: true,
    isNightMode: true,
  },
];

export const DIALOGUES = {
  CATCH: [
    "এইবার ধরা খাইছ!",
    "হেলিকপ্টার চোখ এড়ানো যাবে না!",
    "নকল করলে ছাড় নাই!",
    "শিক্ষা রক্ষা অভিযান সফল!",
  ],
  MISS: [
    "এইটা নকল না!", 
    "ভুল হয়ে গেছে!"
  ],
};

import React from 'react';

interface MainMenuProps {
  onStartGame: () => void;
}

const MainMenu: React.FC<MainMenuProps> = ({ onStartGame }) => {
  return (
    <div className="w-full max-w-md h-full max-h-[600px] bg-blue-500 flex flex-col items-center justify-center p-8 rounded-lg shadow-2xl text-center border-4 border-yellow-400">
      <h1 className="text-5xl md:text-6xl font-extrabold text-white drop-shadow-lg mb-4">Helicopter Inspector</h1>
      <p className="text-yellow-200 text-lg mb-8">Minister Milon is on a mission to ensure fair exams!</p>
      <button
        onClick={onStartGame}
        className="px-8 py-4 bg-green-500 text-white text-2xl font-bold rounded-full shadow-lg hover:bg-green-600 transform hover:scale-105 transition-transform duration-200 border-4 border-white"
      >
        Start Mission
      </button>
      <div className="mt-8 text-sm text-blue-100">
        <p>Use Arrow Keys or WASD to fly.</p>
        <p>Click on cheating students!</p>
      </div>
    </div>
  );
};

export default MainMenu;

import React from 'react';

interface GameOverScreenProps {
  score: number;
  onPlayAgain: () => void;
  message?: string;
}

const GameOverScreen: React.FC<GameOverScreenProps> = ({ score, onPlayAgain, message }) => {
  const defaultMessage = score > 0 ? "Mission Accomplished!" : "Mission Failed. Try Again!";
  return (
    <div className="w-full max-w-md h-full max-h-[600px] bg-red-500 flex flex-col items-center justify-center p-8 rounded-lg shadow-2xl text-center border-4 border-yellow-400">
      <h1 className="text-5xl md:text-6xl font-extrabold text-white drop-shadow-lg mb-4">Game Over</h1>
      <p className="text-yellow-200 text-2xl mb-2">{message || defaultMessage}</p>
      <p className="text-white text-4xl font-bold mb-8">Final Score: {score}</p>
      <button
        onClick={onPlayAgain}
        className="px-8 py-4 bg-blue-500 text-white text-2xl font-bold rounded-full shadow-lg hover:bg-blue-600 transform hover:scale-105 transition-transform duration-200 border-4 border-white"
      >
        Play Again
      </button>
    </div>
  );
};

export default GameOverScreen;

import React from 'react';

interface HUDProps {
  score: number;
  timer: number;
  levelName: string;
}

const HUD: React.FC<HUDProps> = ({ score, timer, levelName }) => {
  const timerColor = timer <= 10 ? 'text-red-500 animate-pulse' : 'text-yellow-300';

  return (
    <div className="absolute top-0 left-0 right-0 bg-black bg-opacity-50 p-2 flex justify-between items-center text-lg md:text-xl font-bold z-20">
      <div className="text-white">Score: <span className="text-green-400">{score}</span></div>
      <div className="text-white">{levelName}</div>
      <div className="text-white">Time: <span className={timerColor}>{timer}</span></div>
    </div>
  );
};

export default HUD;

import React, { useState, useEffect } from 'react';

interface ToastProps {
  message: string;
  type: 'catch' | 'miss';
  onHide: () => void;
}

const Toast: React.FC<ToastProps> = ({ message, type, onHide }) => {
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    if (message) {
      setVisible(true);
      const timer = setTimeout(() => {
        setVisible(false);
        // Allow fade-out animation to complete before calling onHide
        setTimeout(onHide, 500); 
      }, 1500);
      return () => clearTimeout(timer);
    }
  }, [message, onHide]);

  if (!message) return null;

  const bgColor = type === 'catch' ? 'bg-green-500' : 'bg-red-500';

  return (
    <div className={`absolute bottom-5 left-1/2 -translate-x-1/2 px-6 py-3 rounded-full text-white font-bold text-xl shadow-lg z-30 transition-all duration-500 ${bgColor} ${visible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-5'}`}>
      {message}
    </div>
  );
};

export default Toast;

import React from 'react';
import { GAME_WIDTH, GAME_HEIGHT } from '../constants';

interface HelicopterProps {
