export default Helicopter;

import React from 'react';
import { Student as StudentType, CheatType } from '../types';

interface StudentProps {
  student: StudentType;
  onClick: (studentId: number) => void;
}

const CheatIcon: React.FC<{ type: CheatType }> = ({ type }) => {
    switch (type) {
        case CheatType.PAPER:
            return <div title="Cheat Paper" className="text-xl">📝</div>;
        case CheatType.PHONE:
            return <div title="Mobile Phone" className="text-xl">📱</div>;
        case CheatType.WHISPER:
            return <div title="Whispering" className="text-xl">🤫</div>;
        case CheatType.DECOY:
            return <div title="Decoy" className="text-xl">🤔</div>; // Looks like cheating but isn't
        default:
            return null;
    }
}

const Student: React.FC<StudentProps> = ({ student, onClick }) => {
  const handleClick = () => {
    if (!student.isCaught && !student.isFalselyAccused) {
      onClick(student.id);
    }
  };

  let studentStateClasses = "bg-blue-200";
  if (student.isCaught) studentStateClasses = "bg-green-400 opacity-50";
  if (student.isFalselyAccused) studentStateClasses = "bg-red-400 opacity-50";

  return (
    <div
      className={`absolute w-12 h-16 rounded-t-full flex flex-col items-center justify-start p-1 transform transition-all duration-300 ${studentStateClasses}`}
      style={{ left: student.x, top: student.y, transform: `translate(-50%, -50%) scale(${student.isCaught || student.isFalselyAccused ? 0.8 : 1})` }}
      onClick={handleClick}
    >
      <div className="w-8 h-8 rounded-full bg-yellow-200 border-2 border-gray-700 flex items-center justify-center">
        <div className="text-xs text-black font-bold">😐</div>
      </div>
      <div className="w-full h-8 bg-blue-500 rounded-b-lg"></div>
      {student.isCheating && <div className="absolute -top-4"><CheatIcon type={student.cheatType} /></div>}
    </div>
  );
};

export default Student;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Level, Student } from '../types';
import { CheatType } from '../types';
import HUD from './HUD';
import Helicopter from './Helicopter';
import StudentComponent from './Student';
import Toast from './Toast';
import { GAME_WIDTH, GAME_HEIGHT, HELICOPTER_SPEED, SPOTLIGHT_RADIUS, DIALOGUES } from '../constants';

interface GameScreenProps {
  levelConfig: Level;
  onLevelComplete: () => void;
  onGameOver: (score: number) => void;
  score: number;
  setScore: React.Dispatch<React.SetStateAction<number>>;
}

const GameScreen: React.FC<GameScreenProps> = ({ levelConfig, onLevelComplete, onGameOver, score, setScore }) => {
  const [timer, setTimer] = useState(levelConfig.duration);
  const [helicopterPos, setHelicopterPos] = useState({ x: GAME_WIDTH / 2, y: 100 });
  const [students, setStudents] = useState<Student[]>([]);
  const [toast, setToast] = useState<{ message: string, type: 'catch' | 'miss' } | null>(null);
  const [combo, setCombo] = useState(0);
  const gameAreaRef = useRef<HTMLDivElement>(null);

  const keysPressed = useRef<Record<string, boolean>>({}).current;

  // Game Loop for Helicopter Movement
  useEffect(() => {
    const moveHelicopter = () => {
      setHelicopterPos(prev => {
        let newX = prev.x;
        let newY = prev.y;
        if (keysPressed.ArrowLeft || keysPressed.a) newX -= HELICOPTER_SPEED;
        if (keysPressed.ArrowRight || keysPressed.d) newX += HELICOPTER_SPEED;
        if (keysPressed.ArrowUp || keysPressed.w) newY -= HELICOPTER_SPEED;
        if (keysPressed.ArrowDown || keysPressed.s) newY += HELICOPTER_SPEED;

        newX = Math.max(0, Math.min(GAME_WIDTH, newX));
        newY = Math.max(0, Math.min(GAME_HEIGHT, newY));

        return { x: newX, y: newY };
      });
    };

    const interval = setInterval(moveHelicopter, 50); // Move every 50ms
    return () => clearInterval(interval);
  }, [keysPressed]);

  // Keyboard event listeners
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keysPressed[e.key] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keysPressed[e.key] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [keysPressed]);

  // Main game timer
  useEffect(() => {
    if (timer <= 0) {
      onLevelComplete();
      return;
    }
    const countdown = setInterval(() => setTimer(t => t - 1), 1000);
    return () => clearInterval(countdown);
  }, [timer, onLevelComplete]);

  // Student Spawning & Cheating Logic
  useEffect(() => {
    const gameTick = () => {
      // Spawn new students
      if (students.length < levelConfig.maxStudents && Math.random() < 0.5) {
        setStudents(prev => [
            ...prev,
            {
                id: Date.now(),
                x: Math.random() * (GAME_WIDTH - 50) + 25,
                y: Math.random() * (GAME_HEIGHT / 2) + (GAME_HEIGHT / 2) - 50,
                cheatType: CheatType.NONE,
                isCheating: false,
                isCaught: false,
                isFalselyAccused: false,
                cheatTimer: 0
            }
        ]);
      }

      // Update cheating status
      setStudents(prev => prev.map(s => {
        if (s.isCaught || s.isFalselyAccused) return s;

        let { isCheating, cheatType, cheatTimer } = s;

        if (isCheating && cheatTimer > 0) {
            cheatTimer -= 1;
        } else if (isCheating && cheatTimer <= 0) {
            isCheating = false;
            cheatType = CheatType.NONE;
        } else if (!isCheating && Math.random() < levelConfig.cheatingChance / 20) {
            isCheating = true;
            cheatTimer = 5 + Math.random() * 5; // Cheat for 5-10 seconds
            const cheatTypes = [CheatType.PAPER, CheatType.PHONE, CheatType.WHISPER];
            if (levelConfig.hasDecoys) cheatTypes.push(CheatType.DECOY);
            cheatType = cheatTypes[Math.floor(Math.random() * cheatTypes.length)];
        }
        return { ...s, isCheating, cheatType, cheatTimer };
      }));
    };

    const interval = setInterval(gameTick, levelConfig.studentSpawnRate / 2);
    return () => clearInterval(interval);
  }, [students.length, levelConfig]);

  const handleStudentClick = useCallback((studentId: number) => {
    const student = students.find(s => s.id === studentId);
    if (!student) return;

    const dx = student.x - helicopterPos.x;
    const dy = student.y - helicopterPos.y;
    const distance = Math.sqrt(dx * dx + dy * dy);

    if (distance > SPOTLIGHT_RADIUS + 20) { // Give some leeway
        return; // Not in spotlight
    }

    const isActuallyCheating = student.isCheating && student.cheatType !== CheatType.DECOY;

    if (isActuallyCheating) {
      const newCombo = combo + 1;
      const bonus = newCombo > 2 ? (newCombo - 1) * 5 : 0;
      setScore(s => s + 10 + bonus);
      setCombo(newCombo);
      const message = DIALOGUES.CATCH[Math.floor(Math.random() * DIALOGUES.CATCH.length)];
      setToast({ message, type: 'catch' });
      setStudents(prev => prev.map(s => s.id === studentId ? { ...s, isCaught: true, isCheating: false } : s));
    } else {
      setScore(s => Math.max(0, s - 5));
      setCombo(0);
      const message = DIALOGUES.MISS[Math.floor(Math.random() * DIALOGUES.MISS.length)];
      setToast({ message, type: 'miss' });
      setStudents(prev => prev.map(s => s.id === studentId ? { ...s, isFalselyAccused: true, isCheating: false } : s));
    }
  }, [students, helicopterPos, setScore, combo]);

  const spotlightStyle = {
    maskImage: `radial-gradient(circle ${SPOTLIGHT_RADIUS}px at ${helicopterPos.x}px ${helicopterPos.y}px, black 100%, transparent)`,
    WebkitMaskImage: `radial-gradient(circle ${SPOTLIGHT_RADIUS}px at ${helicopterPos.x}px ${helicopterPos.y}px, black 100%, transparent)`,
  };

  return (
    <div
      ref={gameAreaRef}
      className="relative bg-gray-300 w-full max-w-[800px] h-full max-h-[600px] overflow-hidden rounded-lg shadow-2xl border-4 border-gray-700 game-cursor"
      style={{ width: GAME_WIDTH, height: GAME_HEIGHT }}
    >
      <HUD score={score} timer={timer} levelName={levelConfig.name} />

      {/* Game Content */}
      <div className={`w-full h-full ${levelConfig.isNightMode ? '' : 'bg-green-100'}`}>
          <div className={`absolute inset-0 ${levelConfig.isNightMode ? 'bg-gray-800' : ''}`} style={levelConfig.isNightMode ? spotlightStyle : {}}>
              {students.map(student => (
                  <StudentComponent key={student.id} student={student} onClick={handleStudentClick} />
              ))}
          </div>
      </div>

      <Helicopter position={helicopterPos} />

      {/* Visual Spotlight for non-night mode */}
      {!levelConfig.isNightMode && (
          <div 
              className="absolute rounded-full bg-yellow-300 bg-opacity-30 border-2 border-yellow-400 pointer-events-none"
              style={{
                  width: SPOTLIGHT_RADIUS * 2,
                  height: SPOTLIGHT_RADIUS * 2,
                  left: helicopterPos.x,
                  top: helicopterPos.y,
                  transform: 'translate(-50%, -50%)'
              }}
          />
      )}

      {toast && <Toast message={toast.message} type={toast.type} onHide={() => setToast(null)} />}
    </div>
  );
};

export default GameScreen;
